/**
 * Aset lambang instansi.
 *
 * Lambang ditanam sebagai data URI, bukan berkas statis di public/, karena
 * penyajian berkas statis tidak dijamin tersedia pada lingkungan serverless
 * seperti Vercel. Dengan cara ini lambang selalu ikut ter-render bersama HTML.
 *
 * Sumber: lambang Imigrasi "Bhumi Pura Wira Wibawa", PNG 128px, ~6 KB.
 *
 * Ada dua bentuk lambang, dan perbedaannya bukan soal selera:
 *
 *   logo        PNG dengan latar transparan. Dipakai di halaman web, karena
 *               yang menggambarnya adalah peramban.
 *
 *   logo_print  JPEG berlatar putih. Khusus untuk laporan PDF, karena dompdf
 *               menolak menempelkan PNG bila ekstensi gd tidak terpasang:
 *
 *                   Cpdf::addPngFromFile()
 *                   "The PHP GD extension is required, but is not installed."
 *
 *               Runtime PHP di Vercel tidak menyertakan gd, sehingga ekspor
 *               PDF selalu berakhir 500. JPEG ditempel dompdf tanpa gd sama
 *               sekali. Latarnya putih agar menyatu dengan kertas laporan.
 */

return [

    'logo' => 'data:image/png;base64,',

    'logo_print' => 'data:image/jpeg;base64,',

    'logo_alt' => 'Lambang Imigrasi',

